try {
document.execCommand('copy');
CatPaw.showToast('\u{1F4CB} \u5DF2\u8907\u88FD\u65E5\u8A8C\u5167\u5BB9', 'info', 1200);
} catch (_) {
CatPaw.showToast('\u8907\u88FD\u5931\u6557', 'error', 1500);
}
